id ReadFields(CStream_AC* aStream);	virtual void WriteFields(CStream_AC* aStream) const;	//------------------------------------------------------------------------------------	// MacApp overrides.	//------------------------------------------------------------------------------------	virtual IDType GetStandardSignature() const;		// Return the signature of this view.	virtual CControl_AC* DoMakeControl(WindowRef theWindow,										const CRect_AC& boundsRect, 										bool isVisible, bool isEnabled, 										const CStr255_AC& itsTitle);		// Create a native or emulated control.	virtual void DoControlAction(ControlPartCode partCode);		// Notifier			//------------------------------------------------------------------------------------	// UpDown control <-> TNumberText notification	//------------------------------------------------------------------------------------	void SetLinkedNumberTextID(IDType linkedNumberTextID);		// Sets the associated number text view ID.		inline IDType GetLinkedNumberTextID() const { return fLinkedNumberTextID; }		// Gets the associated number text view ID.		TNumberText* GetLinkedNumberText();		// Returns the view, calling a FindSubView if it hasn't been found yet.		protected:	IDType			fLinkedNumberTextID;	TNumberText*	fLinkedNumberText;};#endif // qAppearance || qEmulateStandardControls#endif // __UUPDOWNCONTROL__